from PIL import Image
X='/home/user/Manual-test-Cases/build/obsolete-recheck-2026-10-19/batch/pvs/exhibits/'; O='/home/user/Manual-test-Cases/build/obsolete-recheck-2026-10-19/batch/pvs/comments/'
HEAD='Re-checked on 19 October 2026 on Staging (build v26.40.19-e435950) and Production (build v26.40.19-d2441a9), signed in as Admin, window 1440 x 900 px, zoom 100%.'
def emb(f): i=Image.open(X+f); return f'!{f}|width={i.width//2},height={i.height//2}!'
def panel(line): return '{panel:bgColor=#deebff|borderColor=#0052cc}\n*QA RE-CHECK: '+line+'*\n{panel}\n\n'
T={}
