for k,(pn,bul,img,cap,src,quote,steps) in T.items():
    b=pn+HEAD+'\n'+''.join('* '+x+'\n' for x in bul)+'\n*Production vs Staging*\n'+emb(img)+'\n_'+cap+'_\n\n*Where the expected result comes from*\n'+src+'\n{quote}'+quote+'{quote}\n\n*How to see it yourself*\n'+''.join('# '+s+'\n' for s in steps)
    open(O+k+'.txt','w').write(b); print(k,len(b))
